def clean(df):
    df = df.copy()
    df['Region'] = df['Region'].replace({'north': 'North', 'Nort': 'North', 'east': 'East', 'Suoth': 'South', 'Wst': 'West'})
    df['Price'] = df['Price'].astype(str).str.replace('$', '', regex=False).astype(float)
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    return df[df['Category'] == 'Electronics'].groupby('Region')['Revenue'].sum().to_dict()
